from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class RFScanOperationStatus(SchemaObject):
    status = SchemaField(name="status", not_null=True)
    reason = SchemaField(name="reason", optional=True)
    operation_id = SchemaField(name="operationId", not_null=True)
    has_file = SchemaField(name="hasFile", optional=True)

    def __init__(self, status, reason, operation_id, has_file):
        self.status = status
        self.reason = reason
        self.operation_id = operation_id
        self.has_file = has_file
        super(RFScanOperationStatus, self).__init__()
